-- task_steps la bang DUY NHAT trong schema thuoc so huu 1 aggregate khac
-- (Task) qua Spring Data JDBC @MappedCollection. Khi luu ca aggregate,
-- Spring Data JDBC dung duong batch-insert cho cac TaskStep con, va duong
-- nay can TU GAN gia tri id truoc de doi chieu ket qua sau batch - dieu nay
-- bi Postgres tu choi voi GENERATED ALWAYS AS IDENTITY (chi chap nhan neu
-- them OVERRIDING SYSTEM VALUE, ma framework khong lam). Doi sang
-- GENERATED BY DEFAULT AS IDENTITY de chap nhan gia tri duoc client cung cap.
ALTER TABLE task_steps ALTER COLUMN id SET GENERATED BY DEFAULT;
